/bin/bash -lc "python - <<'PY'
import numpy as np
A=np.load('source_pixels.npz')['rgb'].astype(int)
B=np.median(A[:13],axis=0).astype(int)
for f in range(0,40):
 d=np.max(abs(A[f]-B),axis=2)
 # dynamic pixels in y45:100, ignore exact small static
 m=d>8
 y,x=np.where(m)
 # connected comps 8-neighbor area
 seen=np.zeros(m.shape,bool); cs=[]
 for yy,xx in zip(y,x):
  if seen[yy,xx]:continue
  st=[(yy,xx)]; seen[yy,xx]=1; pts=[]
  while st:
   qy,qx=st.pop();pts.append((qy,qx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=qy+dy,qx+dx
     if 0<=ny<144 and 0<=nx<256 and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;st.append((ny,nx))
  if len(pts)>10:
   py=np.array([p[0] for p in pts]);px=np.array([p[1] for p in pts]);
   if py.min()<100 and py.max()>45: cs.append((len(pts),px.min(),py.min(),px.max(),py.max(),round(px.mean(),1),round(py.mean(),1)))
 print(f, sorted(cs,reverse=True)[:5])
